<?php declare(strict_types=1);$member=$renewalDashboard['member']??null;$policy=$renewalDashboard['policy']??null;$renewal=$renewalDashboard['renewal']??null; ?>
<section class="section"><div class="container-narrow"><div class="section-heading"><p class="eyebrow">Member portal</p><h1>Membership renewal</h1><p>Renewal is completed only after the associated invoice has an exact, server-verified payment.</p></div><?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?>
<?php if(!$member):?><div class="empty-state"><p>No membership record is available.</p></div><?php else:?><article class="admin-panel"><p><strong><?= $e($member['membership_number']??'') ?></strong> · <?= $e($member['grade_name']??'') ?></p><p>Current expiry: <?= $e($member['expires_at']??'Not configured') ?></p><?php if($renewal):?><p>Renewal reference: <strong><?= $e($renewal['renewal_reference']) ?></strong></p><p>Status: <span class="status-pill"><?= $e(ucwords(str_replace('_',' ',$renewal['status']))) ?></span></p><?php if(!empty($renewal['invoice_public_id'])):?><a class="btn btn-navy" href="/account/invoices">Open renewal invoice</a><?php endif;?><?php elseif($policy):?><p>Configured fee: <?= $e($policy['currency']) ?> <?= $e(number_format(((int)$policy['amount_minor'])/100,2)) ?></p><p>Configured period: <?= $e($policy['period_value'].' '.$policy['period_unit']) ?></p><form method="post" action="/account/membership-renewal"><?= $csrf->field() ?><button class="btn btn-navy" type="submit">Generate renewal invoice</button></form><?php else:?><p>No active renewal policy is configured for this membership grade.</p><?php endif;?></article><?php endif;?></div></section>
